package com.oneminute.guesthousemanager;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Bitmap;import java.io.FileOutputStream;import org.json.JSONObject;
final class GuestMessageDesignProbe {
 static Intent item(Context c,int n,String kind)throws Exception{return new Intent(c,MessageAlertActivity.class).putExtra("alertId","synthetic-guest-design-"+n).putExtra("senderLabel","online".equals(kind)?"온라인 게스트":"현장게스트").putExtra("message",kind.equals("online")?"Wan Ting Chung\nHello I will arrive at 3pm~4pm 🙏🙏":"수건 2장 더 받을 수 있을까요?").putExtra("messageType","general").putExtra("guestContext",new JSONObject().put("kind",kind).put("guest",kind.equals("online")?"Wan Ting Chung":"김민수").put("room","501").put("property","One").put("channel",kind.equals("online")?"Airbnb":"").put("arrival","2026-12-25").put("departure","2026-12-26").put("sent","11.13 21:32").toString());}
 static void capture(Instrumentation t,Context c,String name)throws Exception{Bitmap b=t.getUiAutomation().takeScreenshot();try(FileOutputStream f=c.openFileOutput(name,0)){b.compress(Bitmap.CompressFormat.PNG,100,f);}}
 static void run(Instrumentation test){Bundle out=new Bundle();Context c=test.getTargetContext();Activity activity=null;try{
  c.getSharedPreferences("omg_push",0).edit().putString("role","staff").putString("member_id","guest-design-test").commit();NativeMessagePopupQueue.clear(c);Intent online=item(c,1,"online"),onsite=item(c,2,"onsite");activity=test.startActivitySync(online.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MessageAlertActivity a=(MessageAlertActivity)activity;test.waitForIdleSync();Thread.sleep(250);
  MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"온라인 게스트 메세지")!=null,"Online title");MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"온라인 게스트님이 보냈습니다.")==null,"No duplicate subtitle");MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"1건 대기")==null,"One count hidden");MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"501호")!=null,"Room metadata");capture(test,c,"native-guest-online.png");
  test.runOnMainSync(()->a.onNewIntent(onsite));test.waitForIdleSync();MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"2건 대기")!=null,"Two count shown");test.runOnMainSync(()->MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"확인").performClick());test.waitForIdleSync();Thread.sleep(250);MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"현장 게스트 메세지")!=null,"Onsite title");MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"김민수")!=null,"Queue preserves onsite metadata");MessagePopupQueueProbe.check(MessagePopupQueueProbe.text(a.getWindow().getDecorView(),"1건 대기")==null,"Two to one hides count");capture(test,c,"native-guest-onsite.png");out.putString("oms_guest_design","ok");test.finish(-1,out);
 }catch(Throwable e){out.putString("oms_guest_design","failed: "+e);test.finish(0,out);}finally{NativeMessagePopupQueue.clear(c);c.getSharedPreferences("omg_push",0).edit().clear().commit();if(activity!=null){final Activity a=activity;test.runOnMainSync(a::finish);}}}
}
